sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var taskid = current.servicenow_task_id.number;
    if (current.email_subject.includes("PRM Request") || current.email_subject.includes("SSI Request")) {

        var elog_pf = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_log');
        elog_pf.addQuery('subject', current.email_subject); // trade task table
        elog_pf.addQuery('api_response_from_qtrack', 'Sent-Ready');
        elog_pf.query();

        if (elog_pf.next()) {
            if (current.state == 'Processed') {
                elog_pf.api_response_from_qtrack = 'Sent Successfully';
                elog_pf.update();

            } else if (current.state == 'Error') {
                elog_pf.api_response_from_qtrack = 'Error';
                elog_pf.update();

                var failureDescription_pf = "Service Operation Service Qtrack Email Outbound Widget failure, details of the error are as below - ServiceNow Reference -" + current.servicenow_task_id.number + " Email Subject : " + current.email_subject.substring(0, 10) + " Timestamp : " + current.response_date + "Error code : " + current.error_code + "Error Body : " + current.error_body; // MSSOTIQUBE-1358
                var createEventForWidgetFailure_pf = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('WARNING', failureDescription_pf, 'MSSiQubeSNWidget_QTRACK');
            }
        }


    } else {
        if (current.state == 'Processed') {

            //MSSRBXCE-91:Fetching queryId from response_body field
            var resp_body = new global.JSON.parse(current.response_body);
            var queryId = resp_body.data.queryId;

            var elog = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_log');
            elog.addQuery('subject', current.email_subject); // trade task table
            elog.query();
            if (elog.next()) {
                elog.api_response_from_qtrack = 'Sent Successfully';
                //MSSRBXCE-91:Saving queryId in email_query_id field on HSBC Email Log record
                elog.email_query_id = queryId;
                elog.update();
            }
            //-------New code as part of 3250 story for Processed state
            var childtable = new GlideRecord('x_hsb11_hsbcmss_eh_aggregated_trade_email_queue');
            //childtable.addQuery('parent.trade_task_reference.number', taskid);
            childtable.addQuery('parent', elog.email_log); //Defect MSSRBXCE-674,676
            childtable.query();
            while (childtable.next()) {
                var task = childtable.trade_case_task.number;
                var taskNumber = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
                taskNumber.addQuery('number', task);
                taskNumber.query();
                if (taskNumber.next()) {
                    taskNumber.state = 3;
                    taskNumber.update();
                }
            }

        } else if (current.state == 'Error') {
            // MSSOTIQUBE-1690 
            var emailLog = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_log');
            emailLog.addQuery('subject', current.email_subject);
            emailLog.query();
            if (emailLog.next()) {
                emailLog.api_response_from_qtrack = 'Error';
                emailLog.update();
            }
            //-------New code as part of 3250 story for Error state
            var childtableError = new GlideRecord('x_hsb11_hsbcmss_eh_aggregated_trade_email_queue');
            //childtableError.addQuery('parent.trade_task_reference.number', taskid);
            childtableError.addQuery('parent', emailLog.email_log); //Defect MSSRBXCE-674,676: //MSSOTIQUBE-1690
            childtableError.query();
            // Calls the rest message configured to send widget failture details to ITID instance and creates an Event
            while (childtableError.next()) {
                var task1 = childtableError.trade_case_task.number;
                var taskNumber1 = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
                taskNumber1.addQuery('number', task1);
                taskNumber1.query();
                if (taskNumber1.next()) {
                    taskNumber1.state = 7;
                    taskNumber1.update();
                }
            }
            var failureDescription = "Cash Equities Qtrack Email Outbound Widget failure, details of the error are as below - ServiceNow Reference -" + current.servicenow_task_id.number + " Email Subject : " + current.email_subject.substring(0, 10) + " Timestamp : " + current.response_date + "Error code : " + current.error_code + "Error Body : " + current.error_body; // MSSOTIQUBE-1358
            var createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('WARNING', failureDescription, 'MSSiQubeSNWidget_QTRACK');
        }
    }
})(current, previous);
